import * as THREE from '../vendor/three.module.js';
import {DetailBatch,material,surface} from '../visuals/model-kit.js';
import {trails,platforms,roads,lake,islands} from './layout.js';
import {project,routeSample,inside} from './terrain.js';
let leafMaterial;
function foliage(){if(leafMaterial)return leafMaterial;const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');ctx.clearRect(0,0,256,256);let seed=77;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<160;i++){const a=random()*Math.PI*2,r=Math.sqrt(random())*111,x=128+Math.cos(a)*r,y=128+Math.sin(a)*r;ctx.fillStyle=['#668054','#738f5d','#426448','#88a56f'][i%4];ctx.beginPath();ctx.ellipse(x,y,8+random()*11,4+random()*8,a,0,Math.PI*2);ctx.fill();}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;leafMaterial=new THREE.MeshStandardMaterial({map:t,alphaTest:.4,side:THREE.DoubleSide,roughness:1});return leafMaterial;}
export function buildEnvironment(k,terrain){
 const skyCanvas=document.createElement('canvas');skyCanvas.width=1024;skyCanvas.height=512;const skyContext=skyCanvas.getContext('2d'),blue=new THREE.Color('#354e78'),horizon=new THREE.Color('#d7b79a'),night=new THREE.Color('#7c8d96');for(let y=0;y<512;y++){const t=y/512,color=t<.51?blue.clone().lerp(horizon,(t/.51)**1.65):horizon.clone().lerp(night,Math.min(1,(t-.51)*5));skyContext.fillStyle='#'+color.getHexString();skyContext.fillRect(0,y,1024,1);}for(let i=0;i<35;i++){skyContext.fillStyle='rgba(226,216,201,.12)';skyContext.beginPath();skyContext.ellipse((i*173)%1024,115+(i%6)*20,65+(i%4)*20,3+(i%4)*2,.08,0,Math.PI*2);skyContext.fill();}const skyTexture=new THREE.CanvasTexture(skyCanvas);skyTexture.colorSpace=THREE.SRGBColorSpace;const sky=new THREE.Mesh(new THREE.SphereGeometry(1200,40,24),new THREE.MeshBasicMaterial({map:skyTexture,side:THREE.BackSide,fog:false,depthWrite:false}));sky.name='meixi-dusk-sky';sky.renderOrder=-20;k.root.add(sky);
 let seed=971;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;},chunks=new Map(),leafGeo=new THREE.PlaneGeometry(1,1),trunkGeo=new THREE.CylinderGeometry(.7,1,1,7),trunkMat=surface('#77614b','wood');
 function tree(x,z,size){const y=terrain.heightAt(x,z),key=Math.floor(x/100)+','+Math.floor(z/100);let b=chunks.get(key);if(!b){const g=new THREE.Group();g.name='forest-chunk';k.root.add(g);b=new DetailBatch(g);chunks.set(key,b);}const o=new THREE.Object3D();o.position.set(x,y+size*2,z);o.scale.set(size*.15,size*4,size*.15);o.updateMatrix();b.add(trunkGeo,trunkMat,o.matrix);for(let i=0;i<7;i++){const a=i*2.4,xx=x+Math.sin(a)*size*1.2,zz=z+Math.cos(a)*size*1.2,yy=y+size*(4.5+(i%3)*.65);for(const turn of[0,Math.PI/2]){o.position.set(xx,yy,zz);o.rotation.set(.15*Math.sin(i),a+turn,.15*Math.cos(i));o.scale.set(size*4.6,size*4.2,1);o.updateMatrix();b.add(leafGeo,foliage(),o.matrix);}}}
 for(let i=0;i<1250;i++){const x=30+random()*723,z=-170+random()*590;if(!terrain.contains(x,z)||terrain.heightAt(x,z)<5)continue;if(platforms.some(p=>Math.abs(x-p.x)<p.w/2+9&&Math.abs(z-p.z)<p.d/2+9))continue;if(trails.some(r=>routeSample(x,z,r).d<r.width/2+4))continue;if(roads.some(([,ps,w])=>ps.slice(1).some((p,j)=>project(x,z,ps[j],p).d<w/2+12)))continue;tree(x,z,1.1+random()*1.25);}
 for(let i=0;i<130;i++){const a=i/130*Math.PI*2,x=-333+Math.cos(a)*345,z=54+Math.sin(a)*272;if(terrain.contains(x,z)&&!roads.some(([,ps,w])=>ps.slice(1).some((p,j)=>project(x,z,ps[j],p).d<w/2+7)))tree(x,z,.8+random()*.8);}
 for(const x of[-773,-724])for(let i=0;i<5;i++)tree(x-2+i,118,.32);
 for(const b of chunks.values())b.finish();
 for(let i=0;i<95;i++){const x=40+random()*670,z=-100+random()*490;if(!terrain.contains(x,z)||trails.some(r=>routeSample(x,z,r).d<r.width/2+4)||platforms.some(p=>Math.abs(x-p.x)<p.w/2+10&&Math.abs(z-p.z)<p.d/2+10))continue;const r=1+random()*3,geo=new THREE.IcosahedronGeometry(r,1),m=new THREE.Mesh(geo,surface('#898c76'));m.position.set(x,terrain.heightAt(x,z)+r*.3,z);m.scale.set(1,.7,.8);m.rotation.y=random()*6;k.root.add(m);m.castShadow=m.receiveShadow=true;}
 const shape=new THREE.Shape(lake.map(p=>new THREE.Vector2(p[0],-p[1])));for(const island of islands)shape.holes.push(new THREE.Path(island.map(p=>new THREE.Vector2(p[0],-p[1]))));const waterGeo=new THREE.ShapeGeometry(shape);waterGeo.rotateX(-Math.PI/2);waterGeo.translate(0,1.55,0);
 const noise=new Uint8Array(64*64*4);for(let j=0;j<64;j++)for(let i=0;i<64;i++){const p=(j*64+i)*4;noise[p]=128+Math.sin(i*.56+j*.19)*23;noise[p+1]=128+Math.cos(j*.53-i*.13)*23;noise[p+2]=244;noise[p+3]=255;}const normal=new THREE.DataTexture(noise,64,64);normal.wrapS=normal.wrapT=THREE.RepeatWrapping;normal.repeat.set(.04,.04);normal.needsUpdate=true;const waterMat=new THREE.MeshStandardMaterial({color:'#365f72',normalMap:normal,normalScale:new THREE.Vector2(.45,.45),roughness:.22,metalness:.65});const water=new THREE.Mesh(waterGeo,waterMat);water.name='meixi-water';k.root.add(water);
 for(const [i,island]of islands.entries()){const is=new THREE.Shape(island.map(p=>new THREE.Vector2(p[0],-p[1]))),ig=new THREE.ExtrudeGeometry(is,{depth:1.5,bevelEnabled:false});ig.rotateX(-Math.PI/2);ig.translate(0,.6,0);k.mesh(ig,[surface('#83946a'),surface('#9c9f8c','stone')],i?'city-island':'festival-island');}k.bench(-399,12,2.1);k.lamp(-381,12,2.1);k.bench(-618,206,2.1);k.lamp(-617,199,2.1);
 // Simplified southern Taohualing silhouette, outside the playable boundary.
 const mountain=new THREE.SphereGeometry(1,40,18),m=new THREE.Mesh(mountain,material('#587167'));m.scale.set(530,110,170);m.position.set(-435,-15,635);k.root.add(m);
 for(let i=0;i<27;i++){const x=830+(i%3)*43,z=-310+Math.floor(i/3)*80,h=25+(i%6)*16;k.box(x,h/2,z,22,h,27,'#637e85');for(let y=5;y<h;y+=5)k.box(x,y,z-13.6,17,.9,.08,'#b7ba9c');k.box(x,h+.4,z,22.5,.8,28,'#93a6a2');}
 return{water,update:(_dt,t)=>{normal.offset.set(t*.003,t*.0012);sky.position.set(k.api.hero.g.position.x,0,k.api.hero.g.position.z);}};
}
